+    let mut prefix = String::new();
+    if request
+        .get("continue_final_message")
+        .map_or(Ok(false), pydantic_bool)?
+        && let Some(last) = messages.last().filter(|m| m["role"] == "assistant")
+        && let Some(content) = last["content"].as_str()
+    {
+        prefix = content.to_owned();
+        messages.pop();
+    }
