+            return Default::default();
+        }
+        let mut markers = vec![
+            THINK_CLOSE,
+            TOOLS_OPEN,
+            RESPONSE_OPEN,
+            RESPONSE_CLOSE,
+            MESSAGE_CLOSE,
+        ];
